class R {int N=71;String s(boolean P,String[]I){var B=new int[I.length];int j=0;for(var s:I){var a=s.split(",");B[j++]=new Integer(a[0])+N*new Integer(a[1]);}int i=1024,z;while((z=f(B,i++))>0&!P);int p=B[i-2];return P?""+z:p%N+","+p/N;}int f(int[]B,int L){var b=new int[N*N];for(int i=L;i-->0;)b[B[i]]=1;int q[]=new int[N*N],v[]={-N,N,-1,1},h=0,t=1;b[0]=1;for(int S=0,E;h<t;S++)for(E=t;h<E;){int p=q[h++],c=p%N;if(p==N*N-1)return S;for(int d:v){int n=p+d;if(n>=0&n<N*N&&Math.abs(n%N-c)<2&b[n]<1)b[q[t++]=n]=1;}}return-1;}}
